// The playground's welcome (cloud/docs/playground.md): the window the desktop
// opens on. Four short pages say what the visitor is looking at and what to
// try, and its buttons open scenes and the frame's own pages with
// frameos.dispatch, as the desktop's Start menu does.
//
// The page showing is kept with frameos.remember, so it outlasts an
// interpreter that was let go.

const INK = '#111418'
const TEAL = '#1c7c66'
const GREEN = '#8baa3a'
const GOLD = '#c8a247'

const PAGES = [
  { label: 'Welcome', short: 'Welcome' },
  { label: 'Scenes', short: 'Scenes' },
  { label: 'Things to try', short: 'Try' },
  { label: 'Get a frame', short: 'Get one' },
]

let page = null // the page showing, while this interpreter lives

function pageNow() {
  if (page === null) {
    const kept = frameos.recall('page')
    page = typeof kept === 'number' ? kept : 0
  }
  return Math.max(0, Math.min(PAGES.length - 1, page))
}

function go(index) {
  page = index
  frameos.remember('page', index)
}

// The frame's scenes by id, so a button for a scene the playground left out
// is not drawn.
function scenesOf(app) {
  const known = {}
  for (const scene of Array.isArray(app.frame.scenes) ? app.frame.scenes : []) known[scene.id] = scene.name
  return known
}

const openScene = (id) => frameos.dispatch('setCurrentScene', { sceneId: id })
const openControlPanel = () => frameos.dispatch('sceneSettings', { page: 'frame' })
const openPrograms = () => frameos.dispatch('sceneSwitcher', {})

const STORE = 'scene-store'
const TERMINAL = 'terminal-app'

// The Scenes page: a few of the playground's scenes for each kind.
const KINDS = [
  {
    title: 'UI',
    color: TEAL,
    icon: 'M6 3l13 7-6 1.5L10 18z',
    scenes: [
      'form-showcase',
      'to-do',
      'now-playing',
      'calculator',
      'colors',
      'kitchen-sink',
    ],
  },
  {
    title: 'Real time',
    color: GOLD,
    icon: 'M13 2L4 14h7l-1 8 9-12h-7z',
    scenes: [
      '64a15e71-cc27-467b-a69b-c4c28bb77017', // Pixel toys
      '58257360-472f-45ef-9acd-05b4f2b8f067', // Color cycling
      'clock',
      'dvd-logo-bounce',
    ],
  },
  {
    title: 'Dashboards & weather',
    color: '#3a63c4',
    icon: 'M3 21h18M6 17v-5M11 17V6M16 17v-3M21 17V9',
    scenes: [
      '66d900ea-3f43-5652-a19e-4a66988cd902', // Weather
      'weather-demo',
      'map',
      'home',
      'steps',
    ],
  },
  {
    title: 'Photos',
    color: '#c8352b',
    icon: 'M3 5h18v14H3zM3 16l5-5 4 4 3-3 6 6M17 9.5a1.5 1.5 0 1 1-3 0a1.5 1.5 0 1 1 3 0',
    scenes: [
      'gallery',
      '1c1899f7-0e3a-5756-805d-d7b0dae17d67', // Ken Burns slideshow
      '89bb1087-7cb1-4a58-92de-27fb70591907', // Wikimedia Commons
      '1963a421-55ab-477b-bb5b-74c2f58f90c0', // Made in Space
    ],
  },
]

// ------------------------------------------------------------------ pieces

// The FrameOS mark: the frame's two corners and the three squares.
const Mark = ({ size }) => (
  <svg viewBox="340 152 488 568" className={`w-[${size}px] h-[${size}px]`}>
    <path d="M376 437V187H791" fill="none" stroke="currentColor" strokeWidth="46" strokeLinecap="round" strokeLinejoin="round" />
    <path d="M791 505V683H633" fill="none" stroke="currentColor" strokeWidth="46" strokeLinecap="round" strokeLinejoin="round" />
    <rect x="421" y="521" width="121" height="113" rx="12" fill={TEAL} />
    <rect x="553" y="401" width="121" height="113" rx="12" fill={GREEN} />
    <rect x="685" y="282" width="125" height="115" rx="12" fill={GOLD} />
  </svg>
)

const Button = ({ primary, onClick, children }) => (
  <div
    className={
      primary
        ? `flex-none rounded-md px-4 py-2 text-sm font-bold text-white bg-[${TEAL}] hover:bg-[#23927a] active:bg-[#155f4f]`
        : 'flex-none rounded-md px-4 py-2 text-sm font-bold text-[#111418] bg-white border border-[#cfccc3] hover:bg-[#efede6] active:bg-[#e2dfd6]'
    }
    onClick={onClick}
  >
    {children}
  </div>
)

const Heading = ({ children }) => <div className="text-3xl font-bold leading-tight">{children}</div>
const Lead = ({ children }) => <div className="mt-1 text-base leading-snug text-[#3d4148]">{children}</div>
const Text = ({ children }) => <div className="mt-3 text-base leading-normal text-[#3d4148]">{children}</div>

// A small frame on a wall, for the first page.
const MiniFrame = ({ label, children }) => (
  <div className="flex-1 flex flex-col items-center gap-1 min-w-0">
    <div className="w-full h-[82px] flex rounded-[3px] bg-[#2b2622] p-[5px]">
      <div className="flex-1 flex overflow-hidden">{children}</div>
    </div>
    <div className="text-xs text-[#6b6f76]">{label}</div>
  </div>
)

const Agenda = () => (
  <div className="flex-1 flex flex-col gap-[2px] bg-white px-2 py-[4px] text-black">
    <div className="text-[10px] font-bold uppercase">Today</div>
    {[
      ['09:00', 'Standup'],
      ['12:30', 'Lunch with Ana'],
      ['18:00', 'Climbing'],
    ].map(([time, what]) => (
      <div className="flex gap-[6px] text-[10px] leading-tight border-t border-black pt-[2px]">
        <span className="font-bold">{time}</span>
        <span className="truncate">{what}</span>
      </div>
    ))}
  </div>
)

// Six inks, as a color e-paper has them.
const Landscape = () => (
  <svg viewBox="0 0 120 80" preserveAspectRatio="none" className="w-full h-full">
    <rect width="120" height="80" fill="#3a63c4" />
    <circle cx="94" cy="20" r="10" fill="#f2d02c" />
    <path d="M0 52 Q28 34 58 50 T120 44 V80 H0Z" fill="#2e8540" />
    <path d="M0 64 Q44 54 84 64 T120 62 V80 H0Z" fill="#f2d02c" />
    <rect x="22" y="42" width="18" height="13" fill="#ffffff" />
    <path d="M19 43 L31 33 L43 43Z" fill="#c8352b" />
    <rect x="29" y="47" width="5" height="8" fill="#111111" />
  </svg>
)

const Forecast = () => (
  <div className="flex-1 flex items-center justify-center gap-2 bg-gradient-to-b from-[#1e3a8a] to-[#0f172a] text-white">
    <svg viewBox="0 0 24 24" className="w-[30px] h-[30px]">
      <circle cx="12" cy="12" r="5" fill="#fbbf24" />
      <path d="M12 1v3M12 20v3M1 12h3M20 12h3M4.2 4.2l2.1 2.1M17.7 17.7l2.1 2.1M4.2 19.8l2.1-2.1M17.7 6.3l2.1-2.1" stroke="#fbbf24" strokeWidth="2" strokeLinecap="round" />
    </svg>
    <div className="flex flex-col">
      <span className="text-2xl font-bold leading-none">21°</span>
      <span className="text-[10px] text-sky-200">Sunny</span>
    </div>
  </div>
)

// The first page's point: all of this is one small binary.
const Binary = () => (
  <div className={`mt-3 flex flex-col gap-1 rounded-xl bg-[#fbf1d3] border border-[#ecd9a0] px-4 py-[10px] text-[${INK}]`}>
    <span className="text-base font-bold leading-tight">All of this runs in one 3.3 MB binary</span>
    <span className="text-xs leading-snug text-[#5a5240]">
      This includes all ePaper/LCD/OLED drivers, low-memory JPEG/GIF/WebP/PNG rendering, QuickJS with TS and JSX
      support, an SVG renderer with React-style change reconciliation, a flexbox engine built on top of that, with
      Tailwind classes for styling, TTF fonts, touch and gesture handling, LED and buzzer feedback, async fetch, partial
      ePaper rendering, dithered rendering, HTTP server with TLS support, WiFi hotspot setup mode, a windowing desktop,
      FAT32 SD card support, over-the-air updates and an ever expanding scene store with live preview.
    </span>
    <span className="text-xs leading-snug text-[#5a5240]">
      All of this runs natively on an ESP32 or a Raspberry Pi, full screen or windowed. In your browser it is compiled
      to WebAssembly.
    </span>
  </div>
)

// A kind of scene, with a few to open.
const Kind = ({ kind, known }) => (
  <div className="flex flex-col gap-2 rounded-lg bg-white border border-[#e2dfd6] p-3">
    <div className="flex items-center gap-2">
      <div className={`flex-none w-[28px] h-[28px] rounded-md bg-[${kind.color}] flex items-center justify-center text-white`}>
        <svg viewBox="0 0 24 24" className="w-[16px] h-[16px]">
          <path d={kind.icon} fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
      </div>
      <span className="text-base font-bold">{kind.title}</span>
    </div>
    <div className="flex flex-wrap gap-[6px]">
      {kind.scenes
        .filter((id) => known[id])
        .map((id) => (
          <div
            className={`rounded-full px-[10px] py-[3px] text-[13px] bg-[#f6f5f1] border border-[#e2dfd6] hover:border-[${TEAL}] hover:text-[${TEAL}] active:bg-[#efede6]`}
            onClick={() => openScene(id)}
          >
            {known[id]}
          </div>
        ))}
    </div>
  </div>
)

// A thing to try: an icon, what to do, and a button where there is one.
const Tip = ({ icon, title, children, action, onClick, wide }) => (
  <div className="flex gap-3 items-start border-t border-[#e2dfd6] py-3">
    <div className="flex-none w-[36px] h-[36px] rounded-lg bg-white border border-[#e2dfd6] flex items-center justify-center text-[#111418]">
      {icon}
    </div>
    <div className="flex-1 min-w-0 flex flex-col">
      <span className="text-base font-bold">{title}</span>
      <span className="text-sm leading-snug text-[#4b5058]">{children}</span>
      {action && !wide ? (
        <div className="flex mt-2">
          <Button onClick={onClick}>{action}</Button>
        </div>
      ) : null}
    </div>
    {action && wide ? <Button onClick={onClick}>{action}</Button> : null}
  </div>
)

const icon = (d) => (
  <svg viewBox="0 0 24 24" className="w-[20px] h-[20px]">
    <path d={d} fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
  </svg>
)
const WINDOWS = 'M3 5h13v10H3zM3 8h13M8 19h13V9'
const GEAR = 'M12 9a3 3 0 1 0 0 6a3 3 0 0 0 0-6zM12 2v3M12 19v3M2 12h3M19 12h3M4.9 4.9l2.1 2.1M17 17l2.1 2.1M4.9 19.1L7 17M17 7l2.1-2.1'
const SLIDERS = 'M4 6h10M18 6h2M4 12h4M12 12h8M4 18h12M20 18h0M16 4v4M10 10v4M18 16v4'
const BAG = 'M6 8h12l-1 13H7zM9 8V6a3 3 0 0 1 6 0v2'
const PROMPT = 'M4 6l5 6l-5 6M12 18h8'

const Link = ({ host, children }) => (
  <div className="flex flex-col rounded-lg bg-white border border-[#e2dfd6] px-4 py-3">
    <span className={`text-base font-bold text-[${TEAL}]`}>{host}</span>
    <span className="text-sm text-[#4b5058]">{children}</span>
  </div>
)

// ------------------------------------------------------------------ pages

function welcome() {
  return (
    <div className="flex flex-col">
      <Heading>Welcome to FrameOS</Heading>
      <Lead>An operating system for smart frames: e-paper and LCD screens that show one thing well.</Lead>
      <div className="flex gap-4 mt-3">
        <MiniFrame label="E-paper">
          <Agenda />
        </MiniFrame>
        <MiniFrame label="Color e-paper">
          <Landscape />
        </MiniFrame>
        <MiniFrame label="LCD">
          <Forecast />
        </MiniFrame>
      </div>
      <Binary />
    </div>
  )
}

function scenes(app, room) {
  const known = scenesOf(app)
  return (
    <div className="flex flex-col">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <Heading>Every window is a scene</Heading>
        <Button onClick={openPrograms}>Show every scene</Button>
      </div>
      <div className={`mt-4 grid ${room >= 460 ? 'grid-cols-2' : 'grid-cols-1'} gap-3`}>
        {KINDS.map((kind) => (
          <Kind kind={kind} known={known} />
        ))}
      </div>
    </div>
  )
}

function tips(app, room) {
  const known = scenesOf(app)
  const wide = room >= 450
  return (
    <div className="flex flex-col">
      <Heading>Things to try</Heading>
      <div className="mt-3 flex flex-col">
        <Tip icon={icon(WINDOWS)} title="Move the windows around" wide={wide}>
          Drag a window by its title bar, size it from an edge, or fill the screen with the button in its corner.
          Alt+Tab goes from one to the next.
        </Tip>
        <Tip icon={icon(GEAR)} title="Change scene settings" wide={wide}>
          The gear at the left of a title bar opens that scene's settings.
        </Tip>
        <Tip
          icon={icon(SLIDERS)}
          title="Change the desktop"
          action="Control Panel"
          onClick={openControlPanel}
          wide={wide}
        >
          Control Panel is the frame's own settings page. Pick another layout there: macOS, BeOS or Tiling.
        </Tip>
        {known[STORE] ? (
          <Tip
            icon={icon(BAG)}
            title="Find more scenes"
            action="Scene store"
            onClick={() => openScene(STORE)}
            wide={wide}
          >
            The Scene store holds the scenes people have shared. Preview any of them right here.
          </Tip>
        ) : null}
        {known[TERMINAL] ? (
          <Tip icon={icon(PROMPT)} title="Type a command" action="Terminal" onClick={() => openScene(TERMINAL)} wide={wide}>
            The Terminal takes the commands of an ESP32's serial console. Start with help.
          </Tip>
        ) : null}
      </div>
    </div>
  )
}

function getOne() {
  return (
    <div className="flex flex-col">
      <Heading>Put it on a real frame</Heading>
      <Text>
        FrameOS runs on a Raspberry Pi with an e-paper or LCD screen, and on ESP32 boards you can flash from your
        browser. Run your frames from FrameOS Cloud or from a server of your own, and make scenes in the editor or with
        the AI.
      </Text>
      <div className="mt-4 flex flex-col gap-2">
        <Link host="frameos.net">Screens, boards, guides and the docs</Link>
        <Link host="cloud.frameos.net">FrameOS Cloud: your frames and the scene store</Link>
        <Link host="github.com/FrameOS/frameos">The source code. FrameOS is free and open source.</Link>
      </div>
    </div>
  )
}

// ------------------------------------------------------------------ the window

export function get(app, context) {
  const width = (context && context.imageWidth) || app.frame.width
  const wide = width >= 600
  const index = pageNow()
  // The room the page has: the window less the sidebar and the padding.
  const room = width - (wide ? 190 : 0) - 48
  const body = [welcome, scenes, tips, getOne][index](app, room)
  const last = index === PAGES.length - 1

  const nav = PAGES.map((p, i) =>
    wide ? (
      <div
        className={
          i === index
            ? 'flex items-center gap-2 rounded-md px-3 py-2 text-sm font-bold bg-white/10 text-white'
            : 'flex items-center gap-2 rounded-md px-3 py-2 text-sm text-[#b9bec6] hover:bg-white/5 hover:text-white'
        }
        onClick={() => go(i)}
      >
        <div className={`w-[6px] h-[6px] rounded-full ${i === index ? `bg-[${GOLD}]` : 'bg-[#4b5058]'}`} />
        {p.label}
      </div>
    ) : (
      <div
        className={
          i === index
            ? `flex-1 text-center py-2 text-sm font-bold text-white border-b-2 border-[${GOLD}]`
            : 'flex-1 text-center py-2 text-sm text-[#b9bec6] border-b-2 border-transparent'
        }
        onClick={() => go(i)}
      >
        {p.short}
      </div>
    )
  )

  const footer = (
    <div className="flex-none flex items-center gap-2 border-t border-[#e2dfd6] px-6 py-3">
      <span className="flex-1 text-xs text-[#6b6f76]">{`${index + 1} of ${PAGES.length}`}</span>
      {index > 0 ? <Button onClick={() => go(index - 1)}>Back</Button> : null}
      {last ? (
        <Button primary onClick={openPrograms}>
          Start exploring
        </Button>
      ) : (
        <Button primary onClick={() => go(index + 1)}>
          Next
        </Button>
      )}
    </div>
  )

  const content = (
    <div className="flex-1 min-w-0 flex flex-col bg-[#f6f5f1] text-[#111418]">
      <div className="flex-1 overflow-y-auto px-6 py-5">{body}</div>
      {footer}
    </div>
  )

  if (wide) {
    return (
      <div className={`flex bg-[${INK}]`}>
        <div className="flex-none w-[190px] flex flex-col px-3 py-4 text-white">
          <div className="flex items-center gap-2 px-2">
            <Mark size={28} />
            <div className="flex flex-col">
              <span className="text-lg font-bold leading-none">FrameOS</span>
              <span className="text-xs text-[#8a9099]">Playground</span>
            </div>
          </div>
          <div className="mt-6 flex flex-col gap-1">{nav}</div>
          <div className="flex-1" />
          <div className="px-2 text-xs text-[#8a9099]">frameos.net</div>
        </div>
        {content}
      </div>
    )
  }
  return (
    <div className={`flex flex-col bg-[${INK}]`}>
      <div className="flex-none flex items-center gap-2 px-4 pt-3 text-white">
        <Mark size={22} />
        <span className="text-base font-bold">FrameOS</span>
        <span className="text-xs text-[#8a9099]">Playground</span>
      </div>
      <div className="flex-none flex px-2 mt-1">{nav}</div>
      {content}
    </div>
  )
}
